// UpdateOrg changes an organization with f, which may refuse with an error. A new plan must allow the seats in use
// (*SeatLimitError otherwise).
func (s *Store) UpdateOrg(id string, f func(*Org) error) (Org, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	o, ok := s.orgs[id]
	if !ok {
		return Org{}, ErrNotFound
	}
	prev := o.Plan
	if err := f(&o); err != nil {
		return Org{}, err
	}
	o.ID = id
	if err := checkOrg(o); err != nil {
		return Org{}, err
	}
	if o.Plan != prev {
		if c := s.seatsLocked(o); !c.Fits() {
			return Org{}, &SeatLimitError{Limit: c.Limit, Used: c.Used}
		}
	}
	s.orgs[id] = o
	return o, nil
}

// Seats returns how many of an organization's seats are in use, and what its plan allows.
func (s *Store) Seats(orgID string) (SeatCount, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	o, ok := s.orgs[orgID]
	if !ok {
		return SeatCount{}, false
	}
	return s.seatsLocked(o), true
}

// seatsLocked counts the seats in use by an organization: its members who are not viewers, and its pending invites
// (neither accepted nor revoked) who are not viewers. Viewers are free. The caller holds the lock.
func (s *Store) seatsLocked(o Org) SeatCount {
	used := 0
	for _, m := range s.members {
		if m.OrgID == o.ID && m.Role != RoleViewer {
			used++
		}
	}
	for _, inv := range s.invites {
		if inv.OrgID == o.ID && inv.AcceptedAt == nil && inv.RevokedAt == nil && inv.Role != RoleViewer {
			used++
		}
	}
	limit, limited := o.Plan.SeatLimit()
	return SeatCount{Used: used, Limit: limit, Unlimited: !limited}
}

