// seatTest is an organization on the free plan (3 seats) with its owner, who is one seat.
func seatTest(t *testing.T) (*Store, Org, User) {
	t.Helper()
	s := New()
	o, err := s.CreateOrg("Initech", OrgFree, "UTC", 0, t0)
	if err != nil {
		t.Fatal(err)
	}
	owner, err := s.CreateUser("owner@initech.example", "Owner", t0)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.AddMember(o.ID, owner.ID, RoleOwner, t0); err != nil {
		t.Fatal(err)
	}
	return s, o, owner
}

func wantSeats(t *testing.T, s *Store, orgID string, want SeatCount) {
	t.Helper()
	got, ok := s.Seats(orgID)
	if !ok || got != want {
		t.Fatalf("Seats = %+v, %v; want %+v", got, ok, want)
	}
}

func TestSeatsAndInvites(t *testing.T) {
	s, o, owner := seatTest(t)
	wantSeats(t, s, o.ID, SeatCount{Used: 1, Limit: 3})

	member, err := s.CreateInvite(o.ID, "ann@example.com", RoleMember, owner.ID, t0)
	if err != nil {
		t.Fatal(err)
	}
	admin, err := s.CreateInvite(o.ID, "bob@example.com", RoleAdmin, owner.ID, t0)
	if err != nil {
		t.Fatal(err)
	}
	wantSeats(t, s, o.ID, SeatCount{Used: 3, Limit: 3})

	var sl *SeatLimitError
	if _, err := s.CreateInvite(o.ID, "cy@example.com", RoleBilling, owner.ID, t0); !errors.As(err, &sl) || sl.Limit != 3 || sl.Used != 3 {
		t.Fatalf("invite past the limit: %v", err)
	}
	if _, err := s.CreateInvite(o.ID, "dee@example.com", RoleViewer, owner.ID, t0); err != nil {
		t.Fatalf("a viewer invite needs no seat: %v", err)
	}
	wantSeats(t, s, o.ID, SeatCount{Used: 3, Limit: 3})

	// The pending invite holds its seat, so accepting it never needs a new one.
	if _, _, _, err := s.AcceptInvite(member.Token, "Ann", t0); err != nil {
		t.Fatalf("accept: %v", err)
	}
	wantSeats(t, s, o.ID, SeatCount{Used: 3, Limit: 3})

	// Revoking a pending invite frees its seat.
	if _, err := s.RevokeInvite(o.ID, admin.ID, t0); err != nil {
		t.Fatal(err)
	}
	wantSeats(t, s, o.ID, SeatCount{Used: 2, Limit: 3})
	if _, err := s.CreateInvite(o.ID, "cy@example.com", RoleBilling, owner.ID, t0); err != nil {
		t.Fatalf("invite into the freed seat: %v", err)
	}
	wantSeats(t, s, o.ID, SeatCount{Used: 3, Limit: 3})

	if _, ok := s.Seats("org_nope"); ok {
		t.Fatal("Seats of an unknown organization")
	}
}

func TestSeatsForRoleChanges(t *testing.T) {
	s, o, owner := seatTest(t)
	ann, _ := s.CreateUser("ann@example.com", "Ann", t0)
	if _, err := s.AddMember(o.ID, ann.ID, RoleMember, t0); err != nil {
		t.Fatal(err)
	}
	carl, _ := s.CreateUser("carl@example.com", "Carl", t0)
	if _, err := s.AddMember(o.ID, carl.ID, RoleViewer, t0); err != nil {
